    const form = document.getElementById('application-form');
    if (!modal || !form) return;
    modal.addEventListener('hidden.bs.modal', () => { form.reset(); form.elements.original_repo.value = ''; });
    document.querySelectorAll('[data-edit-application]').forEach(button => button.addEventListener('click', () => {
        form.elements.original_repo.value = button.dataset.repo || '';
        form.elements.repo_full_name.value = button.dataset.repo || '';
        form.elements.display_name.value = button.dataset.name || '';
        form.elements.domain.value = button.dataset.domain || '';
        form.elements.environment.value = button.dataset.environment || 'virtuenet';
        form.elements.health_path.value = button.dataset.healthPath || '/health';
        form.elements.department_id.value = button.dataset.department || '';
        form.elements.vps_node_id.value = button.dataset.node || '';
        form.elements.owner_id.value = button.dataset.owner || '';
        form.elements.cost_center.value = button.dataset.costCenter || '';
        form.elements.coolify_uuid.value = button.dataset.coolify || '';
        form.elements.thumbnail_url.value = button.dataset.thumbnail || '';
        form.elements.domain_exception_reason.value = button.dataset.domainException || '';
        form.elements.notes.value = button.dataset.notes || '';
        document.getElementById('application-sync').checked = button.dataset.sync === '1';
        document.getElementById('application-backup').checked = button.dataset.backup === '1';
        bootstrap.Modal.getOrCreateInstance(modal).show();
    }));

    const nodeModal = document.getElementById('node-modal');
    const nodeForm = document.getElementById('node-form');
    nodeModal?.addEventListener('hidden.bs.modal', () => nodeForm.reset());
    document.querySelectorAll('[data-edit-node]').forEach(button => button.addEventListener('click', () => {
        const node = JSON.parse(button.dataset.node);
        Object.entries(node).forEach(([key, value]) => {
            if (nodeForm.elements[key] && key !== 'active') nodeForm.elements[key].value = value ?? '';
        });
        document.getElementById('node-active').checked = Boolean(node.active);
        bootstrap.Modal.getOrCreateInstance(nodeModal).show();
    }));
});
</script>
@endsection
